package com.cowave.search.collection.model

import jakarta.persistence.Column
import jakarta.persistence.Entity
import jakarta.persistence.Id
import jakarta.persistence.Table
import java.util.UUID

/**
 * 컬렉션 설정 엔티티.
 *
 * 기존 ES `.dsearch_collection` 도큐먼트를 RDB로 이전.
 * - A/B 인덱스 상태(health, docsCount 등)는 ES 실시간 조회이므로 저장하지 않음
 * - launcher 설정은 YAML 문자열 그대로 저장 (구조가 자유롭고 인덱서에 그대로 전달됨)
 */
@Entity
@Table(name = "collections")
class Collection(
    @Id
    val id: String = UUID.randomUUID().toString(),
    @Column(nullable = false)
    val clusterId: UUID,
    @Column(nullable = false)
    var name: String,
    @Column(nullable = false)
    var baseId: String,
    @Column(nullable = false)
    var scheduled: Boolean = false,
    var jdbcId: String? = null,
    @Column(columnDefinition = "TEXT")
    var cron: String? = null,
    var sourceName: String? = null,
    @Column(nullable = false)
    var autoRun: Boolean = false,
    var replicas: Int? = null,
    var refreshInterval: Int? = null,
    var ignoreRoleYn: String? = null,
    var indexingType: String? = null,
    @Column(nullable = false)
    var extIndexer: Boolean = false,
    // 외부 인덱서 ES 접속 정보 (extIndexer=true 시 사용)
    var esScheme: String? = null,
    var esHost: String? = null,
    var esPort: String? = null,
    var esUser: String? = null,
    var esPassword: String? = null,
    // 외부 인덱서 런처 설정 (YAML 문자열)
    @Column(columnDefinition = "TEXT")
    var launcherYaml: String? = null,
    // 런처 접속 정보
    var launcherScheme: String? = null,
    var launcherHost: String? = null,
    var launcherPort: String? = null,
)

package com.cowave.search.jdbc.model

import jakarta.persistence.Column
import jakarta.persistence.Entity
import jakarta.persistence.Id
import jakarta.persistence.Table
import java.util.UUID

/**
 * JDBC 연결 설정 엔티티.
 *
 * 기존 ES `.dsearch_jdbc` 도큐먼트를 RDB로 이전.
 * - id: 사용자 지정 식별자 (Collection.jdbcId에서 참조)
 * - clusterId: 어느 클러스터에 속하는지 구분
 */
@Entity
@Table(name = "jdbc_info")
class JdbcInfo(
    @Id
    val id: String = UUID.randomUUID().toString(),
    @Column(nullable = false)
    val clusterId: UUID,
    @Column(nullable = false)
    var name: String,
    @Column(nullable = false)
    var provider: String,
    @Column(nullable = false)
    var driver: String,
    @Column(nullable = false)
    var address: String,
    @Column(nullable = false)
    var port: String,
    @Column(name = "db_name", nullable = false)
    var dbName: String,
    @Column(name = "db_user")
    var user: String? = null,
    var password: String? = null,
    @Column(columnDefinition = "TEXT")
    var url: String? = null,
    @Column(columnDefinition = "TEXT")
    var params: String? = null,
)

package com.cowave.search.common.health

import com.cowave.search.cluster.infrastructure.ClusterRepository
import com.cowave.search.common.elasticsearch.ElasticsearchClientFactory
import org.springframework.boot.actuate.health.Health
import org.springframework.boot.actuate.health.HealthIndicator
import org.springframework.stereotype.Component

/**
 * 등록된 모든 ES 클러스터의 연결 상태를 Actuator health에 노출.
 *
 * - 클러스터가 없으면 UP (정상 초기 상태)
 * - 하나라도 연결 실패 시 전체 상태 DOWN
 * - 각 클러스터의 상세 상태를 detail로 제공
 */
@Component("elasticsearch")
class ElasticsearchHealthIndicator(
    private val clusterRepository: ClusterRepository,
    private val clientFactory: ElasticsearchClientFactory,
) : HealthIndicator {
    override fun health(): Health {
        val clusters = clusterRepository.findAll()

        if (clusters.isEmpty()) {
            return Health.up().withDetail("message", "등록된 클러스터 없음").build()
        }

        val details = mutableMapOf<String, Any>()
        var hasFailure = false

        clusters.forEach { cluster ->
            val status = runCatching {
                val client = clientFactory.getClient(cluster.id)
                val ping = client.ping()
                if (ping.value()) "UP" else "DOWN"
            }.getOrElse { "DOWN: ${it.message}" }

            details["${cluster.name}(${cluster.id})"] = status
            if (!status.startsWith("UP")) hasFailure = true
        }

        return if (hasFailure) {
            Health.down().withDetails(details).build()
        } else {
            Health.up().withDetails(details).build()
        }
    }
}

